package com.ecommerce.review; import com.ecommerce.product.Product; import com.ecommerce.user.User; import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="reviews") public class Review { @Id @GeneratedValue(strategy=GenerationType.UUID) UUID id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="product_id",nullable=false) Product product; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) User user; @Column(nullable=false) short rating; @Column(columnDefinition="TEXT") String comment; @Column(name="created_at",nullable=false,updatable=false) Instant createdAt; @PrePersist void c(){createdAt=Instant.now();} public UUID getId(){return id;} public short getRating(){return rating;} public String getComment(){return comment;} public void setProduct(Product v){product=v;} public void setUser(User v){user=v;} public void setRating(short v){rating=v;} public void setComment(String v){comment=v;} }
